  "inlineSchema": "// This is your Prisma schema file,\n// learn more about it in the docs: https://pris.ly/d/prisma-schema\n\n// Looking for ways to speed up your queries, or scale easily with your serverless or edge functions?\n// Try Prisma Accelerate: https://pris.ly/cli/accelerate-init\n\ngenerator client {\n  provider = \"prisma-client-js\"\n  output   = \"../lib/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"sqlite\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// Enum for distinguishing user roles\nenum UserRole {\n  STUDENT\n  MENTOR\n  ADMIN\n}\n\n// Enum for education levels\nenum EducationLevel {\n  GRADE_9\n  ORDINARY_LEVEL\n  ADVANCED_LEVEL\n}\n\n// Enum for skill levels\nenum SkillLevel {\n  BEGINNER\n  INTERMEDIATE\n  ADVANCED\n}\n\n// Enum for learning styles\nenum LearningStyle {\n  VISUAL\n  HANDS_ON\n  THEORETICAL\n  MIXED\n}\n\n// The main User model, linked to Auth.js\nmodel User {\n  id            String    @id @default(cuid())\n  name          String?\n  email         String?   @unique\n  emailVerified DateTime?\n  image         String?\n  password      String? // Optional hashed password for credentials-based authentication\n  role          UserRole  @default(STUDENT) // Default role on signup. This will be confirmed/updated during the onboarding process.\n\n  // Additional basic information fields for onboarding\n  fullName      String? // Complete full name from onboarding\n  age           Int? // Age from onboarding  \n  contactNumber String? // Phone number from onboarding\n\n  accounts Account[]\n  sessions Session[]\n\n  // One-to-one relationship to a role-specific profile.\n  // A User can be a Student OR a Mentor. The corresponding record will be created during onboarding.\n  student Student?\n  mentor  Mentor?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@map(\"users\")\n}\n\n// Custom model for the Student profile, linked to a User.\nmodel Student {\n  id     String @id @default(cuid())\n  userId String @unique\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  // Academic Background (Part 2)\n  currentEducationLevel EducationLevel?\n  school                String?\n\n  // Subject & Skill Assessment (Part 3)\n  subjectsOfInterest     String? // Comma-separated subjects\n  currentYear            Int? // Current academic year\n  preferredLearningStyle LearningStyle?\n\n  // Learning accommodations\n  hasLearningDisabilities Boolean @default(false)\n  learningAccommodations  String? // Description of accommodations needed\n\n  // Subject skill assessments (one-to-many relationship)\n  subjectSkills SubjectSkill[]\n\n  // Onboarding completion status\n  onboardingCompleted Boolean @default(false)\n  onboardingStep      Int     @default(1) // Track which step they're on (1-3)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@map(\"students\")\n}\n\n// Model to track skill level for each subject\nmodel SubjectSkill {\n  id        String  @id @default(cuid())\n  studentId String\n  student   Student @relation(fields: [studentId], references: [id], onDelete: Cascade)\n\n  subjectName String // Name of the subject\n  skillLevel  SkillLevel // Beginner/Intermediate/Advanced\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Ensure one skill level per subject per student\n  @@unique([studentId, subjectName])\n  @@map(\"subject_skills\")\n}\n\n// Custom model for the Mentor profile, linked to a User.\nmodel Mentor {\n  id     String @id @default(cuid())\n  userId String @unique\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  // Add other mentor-specific fields based on the hackathon case study.\n  professionalRole String?\n  bio              String?\n  expertise        String?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@map(\"mentors\")\n}\n\nmodel Admin {\n  id       String  @id @default(cuid())\n  name     String?\n  email    String? @unique\n  password String? // Optional hashed password for credentials-based authentication\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@map(\"admins\")\n}\n\n// --- Auth.js Required Models ---\n\nmodel Account {\n  id                String  @id @default(cuid())\n  userId            String\n  type              String\n  provider          String\n  providerAccountId String\n  refresh_token     String?\n  access_token      String?\n  expires_at        Int?\n  token_type        String?\n  scope             String?\n  id_token          String?\n  session_state     String?\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@unique([provider, providerAccountId])\n  @@map(\"accounts\")\n}\n\nmodel Session {\n  id           String   @id @default(cuid())\n  sessionToken String   @unique\n  userId       String\n  expires      DateTime\n  user         User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@map(\"sessions\")\n}\n\nmodel VerificationToken {\n  identifier String\n  token      String   @unique\n  expires    DateTime\n\n  @@unique([identifier, token])\n  @@map(\"verification_tokens\")\n}\n\n// Keep the original Sample model for demonstration purposes\nmodel Sample {\n  id String @id @default(cuid())\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@map(\"samples\")\n}\n",
